@@ -13,7 +13,7 @@
     private const ODS_TO_EXCEL = [
         // Sheet names with special characters are quoted with single quotes in ODS
         // e.g. 'Sheet Name'.A1 -> 'Sheet Name'!A1
-        '/\'([^\']+)\'\./' => "'$1'!",
+        '/\'([^\']+)\'\./' => "'$1'!",
         // ODS uses . for multiplication, Excel uses *
         '/\./' => '*',
         // ODS uses , for decimal separator in some locales, but Excel uses .
